import{z as E,x as p,o as l,c as d,q as o,j as t,D as a,d as r,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"K8s 推理工作负载","description":"","frontmatter":{"title":"K8s 推理工作负载","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/k8s-inference.md","filePath":"llm/k8s-inference.md","lastUpdated":1791063341000}'),A={name:"llm/k8s-inference.md"};function c(m,e,P,D,B,u){const n=p("Mermaid");return l(),d("div",null,[e[2]||(e[2]=o('<h1 id="k8s-推理工作负载" tabindex="-1">K8s 推理工作负载 <a class="header-anchor" href="#k8s-推理工作负载" aria-label="Permalink to &quot;K8s 推理工作负载&quot;">​</a></h1><div class="epigraph"><p>Deployment 假定副本无状态、可随时杀掉再拉起；自回归推理的状态在 KV 里，调度单位是 GPU 拓扑与迭代，不是均质的 Pod 整数。</p><footer>—— 对照 Kubernetes Deployment 的副本语义，以及 Orca / vLLM 把调度落在模型迭代上的服务引擎</footer></div><p><a href="/llm/cloudmatrix-infer">上一课</a>用融合算子减少 decode 的 launch 与多余 All-to-All，AIV-Direct 躲开 SDMA 启动税。缺口是把引擎塞进集群时，第一反应往往是 Deployment + <code>replicas: N</code>：那份契约假定 Pod 可互换、滚动可硬杀，生成式推理不成立——每条请求持有 <a href="/llm/paged-attention">分页 KV</a>，TP/EP 必须落在同一通信域。本课把「K8s 上跑推理」写成工作负载类型。不重讲 Prolog/GMM 流水表。后课扩缩默认已经读完：杀掉一个 Pod 等于丢掉该副本上所有会话状态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Deployment 的契约是：任意 <code>n</code> 个就绪 Pod 可互换，滚动更新时先起后杀或先杀后起，水平扩缩只改整数副本。<span class="marginnote">术语翻译：副本（replica）就是同一个服务的多份拷贝，K8s 假定任何一份都能顶替另一份。推理引擎做不到——每份拷贝各自攒着一堆用户的 KV 会话状态，杀掉哪一份，哪一批用户的上下文就没了。</span>推理引擎的契约是：每个副本是一份（或一组）权重加一块 KV 池，进程内还有 <a href="/llm/continuous-batching">连续批</a> 的运行集。杀 Pod 不经过排空，等于对所有在途会话做一次硬抢占且不换出。扩一个副本很慢——要加载数十到数百 GB 权重——缩一个副本很贵——KV 蒸发。副本还不可互换：绑了某租户前缀缓存的那张卡，与刚启动的冷副本，对 TTFT 不是同一个东西。</p><p>默认调度的第二失败是拓扑。要 8 卡 TP 的 Pod，若被拆到两台只有 PCIe 的机器，NCCL/HCCL 会在以太网里死去。超节点上若按 1 卡一个 Pod 铺满，UB 域被切碎，宽 EP 组不起来。Deployment 没有「必须同一 NVLink/UB 域」的一等字段；拓扑管理器与设备插件只能做局部 NUMA 对齐，做不到柜级约束。</p><h3 id="无状态副本-vs-有状态加速器进程" tabindex="-1">无状态副本 vs 有状态加速器进程 <a class="header-anchor" href="#无状态副本-vs-有状态加速器进程" aria-label="Permalink to &quot;无状态副本 vs 有状态加速器进程&quot;">​</a></h3><p>Web 无状态：状态在数据库，Pod 是纯计算。推理有状态：状态的热路径在 HBM。可以把会话 ID 存进 Redis，但下一步 token 仍要本地 KV。因此「K8s 无状态」最多适用于网关、分词、以及把引擎当黑盒调用的前端；引擎本身是有状态的、拓扑敏感的、启动昂贵的工作负载。用 Deployment 硬套，不是风格问题，是语义错误。</p><p><span class="marginnote">Job/CronJob 适合离线批推理：跑完即焚，KV 不必跨 Pod 存活。在线交互、多轮、前缀缓存，都不是 Job。StatefulSet 给出稳定身份，仍不理解 GPU 装箱与迭代级抢占，只比 Deployment 多了有序编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把控制面拆开。入口仍可以是标准 Service / Gateway：OpenAI 兼容 HTTP 见 <a href="/llm/openai-compat-api">协议</a>。后面的引擎不要用 Deployment 的滚动整数去表达。最小可用的自定义是：一种 CRD 描述「一份模型副本」——要多少卡、要哪种互连域、是 P 池还是 D 池、权重来源、最大 KV 块——再由控制器去创建紧密耦合的 Pod 组（或多个容器共享设备），并用扩展调度器做放置。Volcano、Kueue、DRA（Dynamic Resource Allocation）一类机制的共同点是：调度决策看见的是拓扑与配额，而不是只看见 <code>gpu: 8</code>。</p><p>扩缩策略必须是引擎知情的。HPA 按 CPU 加副本，对 decode 几乎总错：CPU 很低，HBM 已满。<span class="marginnote">术语翻译：HPA 是 K8s 自带的自动扩缩组件，指标超阈值就加减副本数。它默认看 CPU 与内存，而 decode 阶段 GPU 算力早已打满、CPU 几乎闲着——用 CPU 扩缩推理服务，就像看厨房灯光亮度判断要不要加厨师。</span>应按队列深度、KV 占用、TTFT/TPOT 违约率来扩，且扩之前要等权重加载完成再接流量。缩容必须先排空：停止新请求、等运行集结束或把 KV <a href="/llm/scale-down-kv">换出/迁移</a>，再删 Pod。<span class="marginnote">「排空」就是只出不进：先停止给该副本派新请求，等在跑的生成完（或把 KV 搬走）再关机。跳过排空直接杀 Pod，等于让所有在线用户话说一半被掐断，这是推理扩缩与普通 Web 服务最大的纪律差别。</span>PD 分离时，P 与 D 是两类工作负载，比率随提示长度变，不能共用一个 <code>replicas</code>。</p>',12)),(l(),t(i,null,{default:a(()=>[s(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GW%5B%22%E7%BD%91%E5%85%B3%20Service%22%5D%20--%3E%20SCH%5B%22%E6%8E%A8%E7%90%86%E6%84%9F%E7%9F%A5%E8%B0%83%E5%BA%A6%22%5D%0A%20%20SCH%20--%3E%20P%5B%22Prefill%20%E5%89%AF%E6%9C%AC%E7%BB%84%22%5D%0A%20%20SCH%20--%3E%20D%5B%22Decode%20%E5%89%AF%E6%9C%AC%E7%BB%84%22%5D%0A%20%20SCH%20--%3E%20C%5B%22%E7%BC%93%E5%AD%98%20%2F%20%E5%89%8D%E7%BC%80%E6%B1%A0%22%5D%0A%20%20DEP%5B%22Deployment%20%E6%95%B4%E6%95%B0%E5%89%AF%E6%9C%AC%22%5D%20-.-%3E%7C%22%E6%97%A0%20KV%20%C2%B7%20%E6%97%A0%E6%8B%93%E6%89%91%22%7C%20X%5B%22%E9%94%99%E8%AF%AF%E6%8A%BD%E8%B1%A1%22%5D%0A%20%20P%20--%3E%7C%22%E5%90%8C%E5%9F%9F%E4%BA%92%E8%BF%9E%22%7C%20FAB%5B%22NVLink%20%2F%20UB%22%5D%0A%20%20D%20--%3E%20FAB%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<h3 id="自定义调度要管的三件事" tabindex="-1">自定义调度要管的三件事 <a class="header-anchor" href="#自定义调度要管的三件事" aria-label="Permalink to &quot;自定义调度要管的三件事&quot;">​</a></h3><p>放置：副本的全体 rank 落在同一 Scale-Up 域，跨域只走 Scale-Out 流量。装箱：多模型、多 LoRA、小请求不要一人独占 8 卡，见 <a href="/llm/gpu-packing">显存装箱</a>。隔离：租户配额与设备切分见 <a href="/llm/multi-tenant-gpu">多租户</a>。这三件事默认 kube-scheduler 的过滤器链做不完，需要设备插件 + 拓扑标签 + 队列（inference queue）上的策略。可以用 Deployment 的，只剩：无 KV 的嵌入服务、纯 CPU 分词、以及单卡、可丢会话、可冷启动的小模型演示。</p><p><span class="marginnote">KServe / InferenceService、llm-d、生产级 vLLM Operator 都在把「推理工作负载」从 Deployment 里抬出来。选哪一个产品不重要，重要的是不要把引擎副本当成 nginx。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Kubernetes 调度是一次绑定：Pod 落到某节点，此后 kubelet 拉起容器。推理调度是持续的：每迭代改运行集，见 <a href="/llm/vllm-scheduler">vLLM 调度器</a>。<span class="marginnote">直觉类比：K8s 调度像给旅客分配座位，落座后就不再管你；推理调度像餐厅领位，每上一道菜（每个迭代）都重新决定谁上桌。两层管的时间尺度差了几个数量级，谁也替代不了谁。</span>两层不要互相代替。集群层决定「这份权重住哪几张卡」；引擎层决定「这毫秒哪些请求进 GPU」。Deployment 把两层压成「有 N 个一样的进程」，既不能在绑定时装箱，也不能在绑定时谈 KV。自定义控制器的合法职责停在集群层：创建、放置、排空、故障迁移；不要在控制器里实现 token 级批处理。</p><p>缩容排空的完整时序值得单独看一遍：</p>',6)),(l(),t(i,null,{default:a(()=>[s(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E7%BC%A9%E5%AE%B9%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20B%5B%22%E5%81%9C%E6%AD%A2%E6%8E%A5%E6%96%B0%E8%AF%B7%E6%B1%82%22%5D%0A%20%20B%20--%3E%20W%7B%22%E8%BF%90%E8%A1%8C%E9%9B%86%E6%98%AF%E5%90%A6%E6%B8%85%E7%A9%BA%22%7D%0A%20%20W%20--%3E%7C%E5%90%A6%7C%20M%5B%22%E7%AD%89%E5%BE%85%E7%94%9F%E6%88%90%E5%AE%8C%E6%88%90%E6%88%96%E8%BF%81%E7%A7%BB%20KV%22%5D%0A%20%20M%20--%3E%20W%0A%20%20W%20--%3E%7C%E6%98%AF%7C%20R%5B%22%E9%87%8A%E6%94%BE%20GPU%20%E4%B8%8E%20KV%20%E6%B1%A0%22%5D%0A%20%20R%20--%3E%20D%5B%22%E5%88%A0%E9%99%A4%20Pod%22%5D%0A%20%20D%20--%3E%20O%5B%22%E9%9B%86%E7%BE%A4%E6%8C%87%E6%A0%87%E6%81%A2%E5%A4%8D%E7%9C%9F%E5%AE%9E%E6%B0%B4%E4%BD%8D%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p>滚动更新的机制也应改成权重版本切换：新副本加载新权重，网关按比例切流，旧副本排空 KV 后再下。对多 LoRA，基座常驻、适配器热更新，更不应为每个适配器起一个 Deployment。</p><h3 id="设备是可分配资源-不是整数标签" tabindex="-1">设备是可分配资源，不是整数标签 <a class="header-anchor" href="#设备是可分配资源-不是整数标签" aria-label="Permalink to &quot;设备是可分配资源，不是整数标签&quot;">​</a></h3><p><code>nvidia.com/gpu: 1</code> 把卡当成可数的球。MIG、超节点份额、整柜 72/384 卡逻辑加速器，都要求更细或更粗的资源对象。DRA 与厂商设备插件把「域」「切片」「内存字节」暴露出来之后，调度器才能拒绝「跨域 TP」。没有这些对象，YAML 里写再多 <code>affinity</code> 也只是启发式，一次节点维修就会把拓扑打散。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>完全抛开 Kubernetes 也可以：Slurm、自研编排、云厂商的模型即服务。K8s 的价值是生态（证书、配置、网关、多租户命名空间），不是它的默认副本语义适合 LLM。不要为了「云原生」把宽 EP 拆成几十个可独立重启的单卡 Deployment。也不要把自定义调度做成第二个 kube-scheduler 却不处理排空：那只是把 Deployment 的杀 Pod 换了个 API。</p><p>混合集群里 CPU 服务继续用 Deployment，推理用 CRD，网关统一对外。观察性要同时拉 Pod 指标与引擎指标（KV 块、批大小、TTFT），否则 HPA 仍会看错信号。</p><p><span class="marginnote">本篇不绑定某一家 Operator 的 CRD 字段。原则是：无状态用 Deployment；有 KV、有拓扑、有 PD 池用自定义工作负载。出处是 Kubernetes 工作负载 API 的语义，加上 Orca（OSDI 2022）与 vLLM（SOSP 2023）把状态放在迭代与块上的事实。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Deployment 的可互换副本、快速杀起、按整数扩缩，与 KV 状态、拓扑域、慢加载的推理引擎冲突。</li><li>集群调度管放置与排空，引擎调度管迭代与块；两层都要，但不能互相冒充。</li><li>在线推理应使用感知 GPU 拓扑与配额的自定义工作负载；Job 留给离线批。</li><li>HPA 应看队列与 SLO，不看 CPU；缩容必须先排空 KV。</li><li>单卡可丢会话的小模型，才是 Deployment 的合理剩余。</li><li>出处：Kubernetes Deployment 语义；Yu et al., Orca, OSDI 2022；Kwon et al., vLLM, SOSP 2023。</li></ul>',9))])}const f=E(A,[["render",c]]);export{C as __pageData,f as default};
